pub const FeedType = enum {
    /// RSS feed.
    rss,
    /// Atom feed.
    atom,
    /// JSON Feed.
    json_feed,
};

/// Hostname/IP allowlist matcher for SSRF policy.
///
/// Serializes as an internally-tagged object so each variant is distinguishable on the
/// wire and round-trips losslessly:
///
/// ```json
/// {"type": "exact",  "value": "api.example.com"}
/// {"type": "suffix", "value": ".example.com"}
/// {"type": "cidr",   "value": "10.0.0.0/8"}
/// ```
///
/// A bare JSON string is still accepted on deserialization and resolves to `Exact`,
/// preserving configs written against the previous untagged representation.
///
/// `Exact`: HostMatcher.Exact
pub const HostMatcher = union(enum) {
    /// Exact hostname match (case-insensitive).
    exact: []const u8,
    /// Suffix match: ".xberg.io" matches "api.xberg.io" and "xberg.io".
    suffix: []const u8,
    /// CIDR match: "10.0.0.0/8" matches IP addresses in that range.
    cidr: []const u8,
};

/// The source of an image reference.
pub const ImageSource = enum {
    /// An `<img>` tag.
    img,
    /// A `<source>` tag inside `<picture>`.
    picture_source,
    /// An `og:image` meta tag.
    og_image,
    /// A `twitter:image` meta tag.
    twitter_image,
};

/// The classification of a link.
pub const LinkType = enum {
    /// A link to the same domain.
    internal,
    /// A link to a different domain.
    external,
    /// A fragment-only link (e.g., `#section`).
    anchor,
    /// A link to a downloadable document (PDF, DOC, etc.).
    document,
};

/// A single page interaction action.
///
/// Actions are serialized with a `type` tag using camelCase naming,
/// except `ExecuteJs` which is explicitly renamed to `"executeJs"`.
pub const PageAction = union(enum) {
    /// Click on an element matching the given CSS selector.
    click: []const u8,
    /// Type text into an element matching the given CSS selector.
    type: struct {
        selector: []const u8,
        text: []const u8,
