/// Crawl multiple seed URLs concurrently, each following links to configured depth.
pub fn batch_crawl(engine: ?[]const u8, urls: []const u8) CrawlError![]u8 {
    const engine_config_z: ?[:0]u8 = if (engine) |v| try std.fmt.allocPrintSentinel(
        std.heap.c_allocator, "{s}", .{v}, 0) else null;
    const engine_config_handle = if (engine_config_z) |z| c.cberg_crawl_config_from_json(z) else 0;
    if (engine_config_z != null and engine_config_handle == 0) return _error_with_message(CrawlError);
    defer if (engine_config_handle != 0) c.cberg_crawl_config_free(engine_config_handle);
    const engine_handle = c.cberg_create_engine(engine_config_handle);
    if (engine_handle == 0) return _error_with_message(CrawlError);
    defer c.cberg_crawl_engine_handle_free(engine_handle);
    // Vec/Map parameters are passed as JSON strings across the FFI boundary.
    const urls_z = try std.fmt.allocPrintSentinel(
        std.heap.c_allocator, "{s}", .{urls}, 0);
    defer std.heap.c_allocator.free(urls_z);
    const _result = c.cberg_batch_crawl(engine_handle, urls_z);
    if (c.cberg_last_error_code() != 0) {
        return _error_with_message(CrawlError);
    }
    if (engine_config_z) |z| std.heap.c_allocator.free(z);
    return blk: {
        if (_result == 0) return error.UnknownFfiError;
        const value = _result;
        defer c.cberg_batch_crawl_results_free(value);
        const _json_ptr = c.cberg_batch_crawl_results_to_json(value);
        if (_json_ptr == null) return error.UnknownFfiError;
        defer _free_string(_json_ptr);
        const slice = std.mem.sliceTo(_json_ptr, 0);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    }
;
}

