/// Create a new crawl engine with the given configuration.
///
/// If `config` is `null`, uses `CrawlConfig.default()`.
/// Returns an error if the configuration is invalid.
pub fn create_engine(config: ?[]const u8) CrawlError!CrawlEngineHandle {
    const config_z: ?[:0]u8 = if (config) |v| try std.fmt.allocPrintSentinel(
        std.heap.c_allocator, "{s}", .{v}, 0) else null;
    defer if (config_z) |z| std.heap.c_allocator.free(z);
    const config_handle = if (config_z) |z| c.cberg_crawl_config_from_json(z) else 0;
    if (config_z != null and config_handle == 0) return _error_with_message(CrawlError);
    defer if (config_handle != 0) c.cberg_crawl_config_free(config_handle);
    const _result = c.cberg_create_engine(config_handle);
    if (c.cberg_last_error_code() != 0) {
        return _error_with_message(CrawlError);
    }
    return blk: { if (_result == 0) return error.UnknownFfiError; break :blk CrawlEngineHandle{ ._handle = _result }; };
}

/// Convert markdown links to numbered citations.
///
/// `[Example](https://example.com)` becomes `Example[1]`
/// with `[1]: https://example.com` in the reference list.
/// Images `!alt` are preserved unchanged.
pub fn generate_citations(markdown: []const u8) error{OutOfMemory}![]u8 {
    const markdown_z = try std.fmt.allocPrintSentinel(
        std.heap.c_allocator, "{s}", .{markdown}, 0);
    defer std.heap.c_allocator.free(markdown_z);
    const _result = c.cberg_generate_citations(markdown_z);
    return blk: {
        if (_result == 0) return error.OutOfMemory;
        const value = _result;
        defer c.cberg_citation_result_free(value);
        const _json_ptr = c.cberg_citation_result_to_json(value);
        if (_json_ptr == null) return error.OutOfMemory;
        defer _free_string(_json_ptr);
        const slice = std.mem.sliceTo(_json_ptr, 0);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    }
;
}

/// Execute browser actions on a single page.
pub fn interact(engine: ?[]const u8, url: []const u8, actions: []const u8) CrawlError![]u8 {
    const engine_config_z: ?[:0]u8 = if (engine) |v| try std.fmt.allocPrintSentinel(
        std.heap.c_allocator, "{s}", .{v}, 0) else null;
    const engine_config_handle = if (engine_config_z) |z| c.cberg_crawl_config_from_json(z) else 0;
    if (engine_config_z != null and engine_config_handle == 0) return _error_with_message(CrawlError);
    defer if (engine_config_handle != 0) c.cberg_crawl_config_free(engine_config_handle);
    const engine_handle = c.cberg_create_engine(engine_config_handle);
    if (engine_handle == 0) return _error_with_message(CrawlError);
    defer c.cberg_crawl_engine_handle_free(engine_handle);
    const url_z = try std.fmt.allocPrintSentinel(
        std.heap.c_allocator, "{s}", .{url}, 0);
    defer std.heap.c_allocator.free(url_z);
    // Vec/Map parameters are passed as JSON strings across the FFI boundary.
    const actions_z = try std.fmt.allocPrintSentinel(
        std.heap.c_allocator, "{s}", .{actions}, 0);
    defer std.heap.c_allocator.free(actions_z);
    const _result = c.cberg_interact(engine_handle, url_z, actions_z);
    if (c.cberg_last_error_code() != 0) {
        return _error_with_message(CrawlError);
    }
    if (engine_config_z) |z| std.heap.c_allocator.free(z);
    return blk: {
        if (_result == 0) return error.UnknownFfiError;
        const value = _result;
        defer c.cberg_interaction_result_free(value);
        const _json_ptr = c.cberg_interaction_result_to_json(value);
        if (_json_ptr == null) return error.UnknownFfiError;
        defer _free_string(_json_ptr);
        const slice = std.mem.sliceTo(_json_ptr, 0);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    }
;
}

