/// Iterator over `CrawlEvent` items in a streaming response.
pub const CrawlStream = struct {
    _handle: u64,

    /// Fetch the next item from the stream, or null at end-of-stream.
    /// Returns an error on mid-stream failure; null on clean EOS.
    pub fn next(self: *CrawlStream) (CrawlError||error{OutOfMemory,HandleClosed})!?CrawlEvent {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _chunk = c.cberg_crawl_engine_handle_crawl_stream_next(handle);
        if (_chunk == 0) {
            // Check errno: 0 = clean EOS, != 0 = error
            if (c.cberg_last_error_code() != 0) return error.UnknownFfiError;
            return null;
        }
        defer c.cberg_crawl_event_free(_chunk);
        const _json = c.cberg_crawl_event_to_json(_chunk);
        if (_json == null) return _error_with_message(CrawlError);
        defer c.cberg_free_string(_json);
        const _json_slice = std.mem.span(_json);
        return try std.json.parseFromSliceLeaky(CrawlEvent, std.heap.c_allocator, _json_slice, .{ .ignore_unknown_fields = true, .allocate = .alloc_always });
    }

    /// Release the underlying stream handle.
    pub fn deinit(self: *CrawlStream) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.cberg_crawl_engine_handle_crawl_stream_free(handle);
    }
};

