/// Opaque handle to a configured crawl engine.
///
/// Constructed via `create_engine` with an optional `CrawlConfig`.
/// Default implementations for all pluggable components are used internally.
pub const CrawlEngineHandle = struct {
    _handle: u64,

    /// Stream a single-URL crawl, yielding `CrawlEvent`s as pages are processed.
    ///
    /// Returns an async stream that emits one event per crawled page, plus a
    /// terminal `Complete` event. On per-URL failure during the crawl, emits an
    /// `Error` event followed by `Complete`. The stream item type is wrapped in
    /// a `Result` to surface transport-level errors; today every emit is `Ok`.
    ///
    /// Language bindings expose this as the native streaming shape for each
    /// target. WASM does not expose native streaming wrappers.
    pub fn crawl_stream(self: *CrawlEngineHandle, req: []const u8) (CrawlError||error{OutOfMemory,HandleClosed})!CrawlStream {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const req_z = try std.heap.c_allocator.dupeZ(u8, req);
        const req_handle = c.cberg_crawl_stream_request_from_json(req_z.ptr);
        std.heap.c_allocator.free(req_z);
        if (req_handle == 0) { return error.UnknownFfiError; }
        defer c.cberg_crawl_stream_request_free(req_handle);
        const _stream_handle = c.cberg_crawl_engine_handle_crawl_stream_start(handle, req_handle);
        if (_stream_handle == 0) { return error.UnknownFfiError; }
        return CrawlStream{ ._handle = _stream_handle };
    }

    /// Stream a multi-URL crawl, yielding `CrawlEvent`s across all seeds.
    ///
    /// Returns an async stream that emits one event per crawled page across all
    /// seeds, plus terminal `Complete` and `Error` events as appropriate. The
    /// stream item type is wrapped in a `Result` to surface transport-level
    /// errors; today every emit is `Ok`.
    ///
    /// Language bindings expose this as the native streaming shape for each
    /// target. WASM does not expose native streaming wrappers.
    pub fn batch_crawl_stream(self: *CrawlEngineHandle, req: []const u8) (CrawlError||error{OutOfMemory,HandleClosed})!BatchCrawlStream {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const req_z = try std.heap.c_allocator.dupeZ(u8, req);
        const req_handle = c.cberg_batch_crawl_stream_request_from_json(req_z.ptr);
        std.heap.c_allocator.free(req_z);
        if (req_handle == 0) { return error.UnknownFfiError; }
        defer c.cberg_batch_crawl_stream_request_free(req_handle);
        const _stream_handle = c.cberg_crawl_engine_handle_batch_crawl_stream_start(handle, req_handle);
        if (_stream_handle == 0) { return error.UnknownFfiError; }
        return BatchCrawlStream{ ._handle = _stream_handle };
    }

    /// Release the underlying FFI handle. Safe to call more than once.
    pub fn free(self: *CrawlEngineHandle) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.cberg_crawl_engine_handle_free(handle);
    }
};
